import { atom, read, update } from 'claude-code'
import type { EngineInterface, ModelUsage, Register, RenderElement, SessionContextUsage, TurnStepResult } from 'claude-code'

import type { Detail, FileArea, FileEntry, GrepHit, History, Phase, Search, Snapshot, Stats, Usage4 } from '../types'
import {
  LOG_DATE, LOG_FORMAT, addUsage, buildEntries, cleanLine, clipW, diffArgv, fitPath, fmtMs, fmtTokens, grepArgv,
  keepSelection, padW, parseBlame, parseDiffRows, parseGrep, parseLog, parseNoIndexNumstat, parseNumstat,
  parseStatus, step, toDiffBody, width,
} from './git'
import type { DiffRow, NumStat } from './git'

const PANE = 'changes'
const TITLE = '当前改动'
const GIT = ['git', '--no-optional-locks', '-c', 'core.quotepath=off']
// ponytail: 文件数上限，超大工作区（未忽略的 node_modules）只列前面这些。
const MAX_FILES = 500
const MAX_UNTRACKED_STATS = 200

const FRESH_STATS: Stats = {
  model: null,
  phase: 'idle',
  turnStartedAt: null,
  turnDurationMs: null,
  turnRequests: 0,
  turnTools: 0,
  turnUsage: null,
  last: null,
  session: { requests: 0, tools: 0, usage: null },
  context: { tokens: null, window: null, percent: null },
}

const snapshotA = atom({ plugin: 'changes-dashboard', key: 'snapshot' } as const, { kind: 'loading' })
const selectedA = atom({ plugin: 'changes-dashboard', key: 'selected' } as const, null)
const detailA = atom({ plugin: 'changes-dashboard', key: 'detail' } as const, null)
const scrollA = atom({ plugin: 'changes-dashboard', key: 'scroll' } as const, { id: null, diff: 0, list: 0 })
const statsA = atom({ plugin: 'changes-dashboard', key: 'stats' } as const, FRESH_STATS)
const nowA = atom({ plugin: 'changes-dashboard', key: 'now' } as const, 0)
const compactA = atom({ plugin: 'changes-dashboard', key: 'compact' } as const, false)
const modeA = atom({ plugin: 'changes-dashboard', key: 'mode' } as const, 'changes')
const EMPTY_SEARCH: Search = { query: '', status: 'idle', hits: [], isCut: false, reason: null }
const searchA = atom({ plugin: 'changes-dashboard', key: 'search' } as const, EMPTY_SEARCH)
const hitSelA = atom({ plugin: 'changes-dashboard', key: 'hitSel' } as const, null)
const hitScrollA = atom({ plugin: 'changes-dashboard', key: 'hitScroll' } as const, 0)
const historyA = atom({ plugin: 'changes-dashboard', key: 'history' } as const, null)
// ponytail: 搜索最多留 300 条结果、提交记录最多 10 条；要更多再加翻页。
const MAX_HITS = 300
const MAX_COMMITS = 10

type $T = EngineInterface

const AREA_LABEL: Record<FileArea, string> = { staged: '已暂存', unstaged: '未暂存', untracked: '未跟踪' }
const PHASE_LABEL: Record<Phase, string> = {
  idle: '等待',
  requesting: '请求中',
  tool: '工具执行中',
  done: '完成',
  aborted: '中断',
  refused: '已拒绝',
  error: '出错',
}
const PHASE_COLOR: Record<Phase, string> = {
  idle: 'inactive',
  requesting: 'claude',
  tool: 'warning',
  done: 'success',
  aborted: 'warning',
  refused: 'error',
  error: 'error',
}

function codeColor(code: string): string {
  if (code === 'A' || code === '?') return 'success'
  if (code === 'D' || code === 'U') return 'error'
  if (code === 'R' || code === 'C') return 'suggestion'
  return 'warning'
}

function clamp(n: number, lo: number, hi: number): number {
  return Math.max(lo, Math.min(hi, n))
}

function firstLine(s: string): string {
  return s.trim().split('\n')[0] ?? ''
}

function toUsage4(u: ModelUsage): Usage4 {
  return {
    input: u.input_tokens,
    output: u.output_tokens,
    cacheRead: u.cache_read_input_tokens,
    cacheWrite: u.cache_creation_input_tokens,
  }
}

/** 列表区的一行：分组标题，或一个文件。 */
type ListRow = { kind: 'head'; label: string } | { kind: 'file'; file: FileEntry }

function listRowsOf(files: readonly FileEntry[]): ListRow[] {
  const rows: ListRow[] = []
  for (const area of ['staged', 'unstaged', 'untracked'] as const) {
    const group = files.filter(f => f.area === area)
    if (group.length === 0) continue
    rows.push({ kind: 'head', label: `${AREA_LABEL[area]} ${group.length}` })
    for (const file of group) rows.push({ kind: 'file', file })
  }
  return rows
}

/** 上一次绘制时各区域的位置和大小，滚动和 j/k 按它换算。 */
const layout = { listTop: 2, listRows: 0, listLen: 0, diffRows: 0, diffLen: 0, detailId: null as string | null }

function listIndexOf(files: readonly FileEntry[], id: string | null): number {
  return listRowsOf(files).findIndex(r => r.kind === 'file' && r.file.id === id)
}

function listOffsetFor(index: number, offset: number): number {
  if (index < 0 || layout.listRows <= 0) return offset
  if (index < offset) return index
  if (index >= offset + layout.listRows) return index - layout.listRows + 1
  return offset
}

// 模块变量：热重载后清零，只放可丢的东西。
let isRunning = false
let isAgain = false
let pending: { cancel: () => void } | undefined
let ticker: { cancel: () => void } | undefined
let rowsCache: { source: string; rows: DiffRow[] } | undefined

function git($: $T, cwd: string, args: string[]) {
  return $.process.run([...GIT, ...args], { cwd, timeoutMs: 20000 })
}

async function scan($: $T): Promise<Snapshot> {
  const cwd = await $.session.cwd()
  let top
  try {
    top = await git($, cwd, ['rev-parse', '--show-toplevel'])
  } catch (err) {
    return { kind: 'error', reason: `无法运行 git：${String(err)}` }
  }
  if (top.exitCode !== 0) return { kind: 'not-git', reason: firstLine(top.stderr) || cwd }
  const root = top.stdout.trim()
  const [st, cached, work, branch] = await Promise.all([
    git($, root, ['status', '--porcelain=v1', '-z', '--untracked-files=all']),
    git($, root, ['diff', '--cached', '--numstat', '-z', '-M']),
    git($, root, ['diff', '--numstat', '-z']),
    git($, root, ['branch', '--show-current']),
  ])
  if (st.exitCode !== 0) return { kind: 'error', reason: firstLine(st.stderr) || 'git status 失败' }
  const status = parseStatus(st.stdout).slice(0, MAX_FILES)
  const untracked = new Map<string, NumStat>()
  const paths = status.filter(s => s.xy === '??').map(s => s.path).slice(0, MAX_UNTRACKED_STATS)
  // ponytail: 每个未跟踪文件跑一次 git diff --no-index，每批 16 个。
  for (let i = 0; i < paths.length; i += 16) {
    await Promise.all(paths.slice(i, i + 16).map(async path => {
      const r = await git($, root, ['diff', '--no-index', '--numstat', '--', '/dev/null', path]).catch(() => undefined)
      const stat = r && parseNoIndexNumstat(r.stdout)
      if (stat) untracked.set(path, stat)
    }))
  }
  return {
    kind: 'ok',
    root,
    branch: branch.stdout.trim() || 'HEAD（游离）',
    files: buildEntries(status, parseNumstat(cached.stdout), parseNumstat(work.stdout), untracked),
  }
}

async function setDetail($: $T, detail: Detail | null) {
  const prev = await read($, detailA)
  if (JSON.stringify(prev) !== JSON.stringify(detail)) await update($, detailA, () => detail)
}

async function loadDetail($: $T, id: string | null, showLoading: boolean) {
  if (id === null) return setDetail($, null)
  const snap = await read($, snapshotA)
  const entry = snap.kind === 'ok' ? snap.files.find(f => f.id === id) : undefined
  if (snap.kind !== 'ok' || entry === undefined) return setDetail($, null)
  if (entry.isBinary) return setDetail($, { id, kind: 'binary' })
  if (showLoading) await setDetail($, { id, kind: 'loading' })
  let detail: Detail
  try {
    const r = await git($, snap.root, diffArgv(entry))
    // --no-index 有差异时退出码是 1，不算失败。
    if (r.exitCode > 1) detail = { id, kind: 'error', reason: firstLine(r.stderr) || `git diff 退出码 ${r.exitCode}` }
    else detail = { id, ...toDiffBody(r.stdout, r.isStdoutTruncated) }
  } catch (err) {
    detail = { id, kind: 'error', reason: String(err) }
  }
  // 读的过程中换了文件，就丢掉这次结果。
  if ((await read($, selectedA)) === id) await setDetail($, detail)
}

async function refreshOnce($: $T) {
  const snap = await scan($)
  const prev = await read($, snapshotA)
  if (JSON.stringify(prev) !== JSON.stringify(snap)) await update($, snapshotA, () => snap)
  const current = await read($, selectedA)
  const next = keepSelection(snap.kind === 'ok' ? snap.files : [], current)
  if (next !== current) {
    await update($, selectedA, () => next)
    await update($, scrollA, s => ({ ...s, id: next, diff: 0 }))
  }
  // 同一个文件刷新时不显示“读取中”，避免闪烁；阅读位置保持不变。
  await loadDetail($, next, next !== current)
}

async function refresh($: $T) {
  if (isRunning) {
    isAgain = true
    return
  }
  isRunning = true
  try {
    do {
      isAgain = false
      await refreshOnce($)
    } while (isAgain)
  } finally {
    isRunning = false
  }
}

/** Claude 连续改文件时合并成一次刷新。 */
function scheduleRefresh($: $T) {
  pending?.cancel()
  pending = $.clock.after(400, () => {
    pending = undefined
    void refresh($)
  })
}

async function select($: $T, id: string) {
  const snap = await read($, snapshotA)
  const index = listIndexOf(snap.kind === 'ok' ? snap.files : [], id)
  await update($, selectedA, () => id)
  await update($, scrollA, s => ({ id, diff: 0, list: listOffsetFor(index, s.list) }))
  await loadDetail($, id, true)
}

async function move($: $T, by: 1 | -1) {
  const snap = await read($, snapshotA)
  const next = step(snap.kind === 'ok' ? snap.files : [], await read($, selectedA), by)
  if (next !== null) await select($, next)
}

async function scrollDiff($: $T, by: number) {
  const max = Math.max(0, layout.diffLen - layout.diffRows)
  await update($, scrollA, s => {
    const base = s.id === layout.detailId ? s.diff : 0
    return { ...s, id: layout.detailId, diff: clamp(base + by, 0, max) }
  })
}

async function setContext($: $T, context: SessionContextUsage) {
  const next = { tokens: context.tokens ?? null, window: context.window || null, percent: context.percent ?? null }
  await update($, statsA, (s): Stats => ({ ...s, context: next }))
}

async function openPane($: $T, focus: boolean) {
  return $.ui.open({ id: PANE, title: TITLE, columns: 72, rows: 24, ...(focus ? { focus: true as const } : {}) })
}

/** 快捷键和状态栏按钮共用：侧栏没开或被别的标签挡住就打开并聚焦，正在显示就关掉。 */
async function togglePane($: $T) {
  const pane = (await $.ui.panes()).find(p => p.id === PANE)
  if (pane?.isShown && pane.isPlaced) {
    await $.ui.close({ id: PANE })
    return
  }
  await $.store.delete('closedByPerson')
  await openPane($, true)
  void refresh($)
}

/** Claude 第一次改文件时自动打开侧栏，和内置 diff 面板一样；人手动关过就不再自动开。 */
async function autoOpen($: $T) {
  if ((await $.store.get('closedByPerson')) === true) return
  if ((await $.ui.panes()).some(p => p.id === PANE)) return
  await openPane($, false)
}

// —— 搜索 ——

const hitId = (h: GrepHit) => `${h.path}:${h.line}`

/** 搜索结果列表上一次绘制的行数，j/k 滚动用。 */
const hitLayout = { rows: 0 }

async function repoRoot($: $T): Promise<string | null> {
  const snap = await read($, snapshotA)
  if (snap.kind === 'ok') return snap.root
  const r = await git($, await $.session.cwd(), ['rev-parse', '--show-toplevel']).catch(() => undefined)
  return r && r.exitCode === 0 ? r.stdout.trim() : null
}

async function runSearch($: $T, raw: string) {
  const query = raw.trim()
  if (query === '') {
    await update($, searchA, () => EMPTY_SEARCH)
    await update($, hitSelA, () => null)
    await update($, historyA, () => null)
    return
  }
  await update($, searchA, (): Search => ({ ...EMPTY_SEARCH, query, status: 'running' }))
  const root = await repoRoot($)
  if (root === null) {
    await update($, searchA, (): Search => ({ ...EMPTY_SEARCH, query, status: 'error', reason: '当前目录不是 Git 仓库' }))
    return
  }
  let next: Search
  try {
    const r = await git($, root, grepArgv(query))
    // git grep 没有匹配时退出码是 1。
    if (r.exitCode > 1) next = { ...EMPTY_SEARCH, query, status: 'error', reason: firstLine(r.stderr) || `git grep 退出码 ${r.exitCode}` }
    else next = { query, status: 'done', reason: null, ...parseGrep(r.stdout, MAX_HITS) }
  } catch (err) {
    next = { ...EMPTY_SEARCH, query, status: 'error', reason: String(err) }
  }
  // 搜索期间又输入了新的词，就丢掉这次结果。
  if ((await read($, searchA)).query !== query) return
  await update($, searchA, () => next)
  await update($, hitScrollA, () => 0)
  const first = next.hits[0]
  await update($, hitSelA, () => (first ? hitId(first) : null))
  await loadHistory($, first ?? null)
}

/**
 * 读某一处结果那一行的提交记录。
 *
 * 先用 git blame 找到这一行最后一次被哪个提交改、在那次提交里是第几行，
 * 再从那个提交起用 `git log -L` 往前追这一行的每次修改。这样工作区有未提交
 * 改动、行号已经错位时，追的仍是同一行。
 */
async function loadHistory($: $T, hit: GrepHit | null) {
  if (hit === null) return update($, historyA, () => null)
  const id = hitId(hit)
  const root = await repoRoot($)
  if (root === null) return update($, historyA, (): History => ({ id, kind: 'error', reason: '当前目录不是 Git 仓库' }))
  await update($, historyA, (): History => ({ id, kind: 'loading' }))
  let next: History
  try {
    const blame = await git($, root, ['blame', '--porcelain', '-L', `${hit.line},${hit.line}`, '--', hit.path])
    const b = blame.exitCode === 0 ? parseBlame(blame.stdout) ?? null : null
    if (b === null) next = { id, kind: 'ok', blame: null, note: '这个文件还没有提交过（未跟踪），没有提交记录。', commits: [] }
    else if (b.isUncommitted) next = { id, kind: 'ok', blame: null, note: '这一行是未提交的改动，还没有提交记录。', commits: [] }
    else {
      const log = await git($, root, [
        'log', `-n${MAX_COMMITS}`, '-s', LOG_FORMAT, LOG_DATE,
        `-L${b.origLine},${b.origLine}:${b.origPath}`, b.hash,
      ])
      if (log.exitCode !== 0) next = { id, kind: 'error', reason: firstLine(log.stderr) || `git log 退出码 ${log.exitCode}` }
      else next = { id, kind: 'ok', blame: b, note: null, commits: parseLog(log.stdout) }
    }
  } catch (err) {
    next = { id, kind: 'error', reason: String(err) }
  }
  if ((await read($, hitSelA)) === id) await update($, historyA, () => next)
}

async function selectHit($: $T, hit: GrepHit) {
  await update($, hitSelA, () => hitId(hit))
  await loadHistory($, hit)
}

async function moveHit($: $T, by: 1 | -1) {
  const { hits } = await read($, searchA)
  const current = await read($, hitSelA)
  const index = hits.findIndex(hit => hitId(hit) === current)
  const next = hits[clamp(index < 0 ? 0 : index + by, 0, Math.max(0, hits.length - 1))]
  if (!next) return
  const nextIndex = hits.indexOf(next)
  await update($, hitScrollA, off => {
    if (hitLayout.rows <= 0) return off
    if (nextIndex < off) return nextIndex
    if (nextIndex >= off + hitLayout.rows) return nextIndex - hitLayout.rows + 1
    return off
  })
  await selectHit($, next)
}

async function setMode($: $T, mode: 'changes' | 'search') {
  await update($, modeA, () => mode)
  if (mode === 'search') void $.ui.focus({ requestId: PANE, key: 'q' }).catch(() => undefined)
}

export const register: Register = on => {
  // —— 会话与命令 ——

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'changes', description: '打开或聚焦“当前改动”侧栏' })
    await $.command.register({ name: 'search', description: '在仓库文件里搜索文字，并查看命中那一行的提交记录', argumentHint: '[文字]' })
    await $.command.register({ name: 'request-info', description: '查看最近一次请求、本轮和整个会话的 token 用量' })
    const [model, usage] = await Promise.all([
      $.session.model().catch(() => null),
      $.session.usage().catch(() => undefined),
    ])
    await update($, statsA, (s): Stats => ({ ...s, model: s.model ?? model }))
    if (usage) await setContext($, usage.context)
    void refresh($)
    // 人手动关过侧栏，就不在新会话里自动打开，直到再运行 /changes。
    if (e.isInteractive && (await $.store.get('closedByPerson')) !== true) {
      const isUp = (await $.ui.panes()).some(p => p.id === PANE)
      if (!isUp) void openPane($, false)
    }
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      await update($, statsA, (s): Stats => ({ ...FRESH_STATS, model: s.model, context: s.context }))
    }
    return next(e)
  })

  on('ui.close', { id: PANE }, async ($, e, next) => {
    if (e.origin.kind === 'person') await $.store.set('closedByPerson', true)
    return next(e)
  })

  on('command.run', { command: 'changes' }, async ($, e) => {
    await update($, modeA, () => 'changes')
    await $.store.delete('closedByPerson')
    await openPane($, true)
    void refresh($)
    const selected = await read($, selectedA)
    if (selected !== null) void $.ui.focus({ requestId: PANE, key: `file:${selected}` }).catch(() => undefined)
    return {
      text: e.presentation.isFullscreen
        ? '“当前改动”侧栏已打开。Esc 回到输入框，Ctrl+X Tab 再次聚焦。'
        : '“当前改动”已在输入框上方打开。当前不是全屏模式，侧栏不能停靠在右侧。',
    }
  })

  on('command.run', { command: 'search' }, async ($, e) => {
    await update($, modeA, () => 'search')
    await openPane($, true)
    const query = e.args.trim()
    if (query !== '') await runSearch($, query)
    else void $.ui.focus({ requestId: PANE, key: 'q' }).catch(() => undefined)
    if (query === '') return { text: '已切到搜索。输入文字后回车。' }
    const { hits, isCut, status, reason } = await read($, searchA)
    if (status === 'error') return { text: `搜索失败：${reason}` }
    return { text: `“${query}”找到 ${hits.length}${isCut ? '+' : ''} 处，结果在侧栏里。` }
  })

  on('command.run', { command: 'request-info' }, async $ => {
    await update($, compactA, () => false)
    return { text: infoLines(await read($, statsA), await $.clock.now()).join('\n') }
  })

  // —— 请求统计：只算主对话 ——

  on('turn.start', async ($, e, next) => {
    const t = await $.clock.now()
    const model = await $.session.model().catch(() => null)
    await update($, statsA, (s): Stats => ({
      ...s,
      model: model ?? s.model,
      phase: 'requesting',
      turnStartedAt: t,
      turnDurationMs: null,
      turnRequests: 0,
      turnTools: 0,
      turnUsage: null,
    }))
    await update($, nowA, () => t)
    ticker?.cancel()
    ticker = $.clock.every(1000, () => {
      void $.clock.now().then(n => update($, nowA, () => n))
    })
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) return yield* next(e)
    const t0 = await $.clock.now()
    await update($, statsA, (s): Stats => ({
      ...s,
      phase: 'requesting',
      turnRequests: s.turnRequests + 1,
      session: { ...s.session, requests: s.session.requests + 1 },
    }))
    let result: TurnStepResult | undefined
    try {
      result = yield* next(e)
      return result
    } finally {
      const t1 = await $.clock.now()
      const answered = result
      const usage = answered?.usage ? toUsage4(answered.usage) : null
      const tools = answered?.toolUses.length ?? 0
      await update($, statsA, (s): Stats => ({
        ...s,
        model: answered?.usage?.model ?? e.model,
        phase: tools > 0 ? 'tool' : s.phase,
        last: {
          model: answered?.usage?.model ?? e.model,
          usage,
          durationMs: t1 - t0,
          stopReason: answered?.stopReason ?? null,
          tools,
        },
        turnUsage: usage ? addUsage(s.turnUsage, usage) : s.turnUsage,
        session: { ...s.session, usage: usage ? addUsage(s.session.usage, usage) : s.session.usage },
      }))
    }
  })

  on('tool.call', async ($, e, next) => {
    if (e.agentId === undefined) {
      await update($, statsA, (s): Stats => ({
        ...s,
        phase: 'tool',
        turnTools: s.turnTools + 1,
        session: { ...s.session, tools: s.session.tools + 1 },
      }))
    }
    const ran = await next(e)
    // 子代理改的文件也要刷新；只读工具不触发。
    if (ran.deny === undefined && ran.isReadOnly !== true) {
      scheduleRefresh($)
      void autoOpen($).catch(() => undefined)
    }
    return ran
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      ticker?.cancel()
      ticker = undefined
      const phase: Phase =
        e.reason === 'answer' ? 'done' : e.reason === 'aborted' ? 'aborted' : e.reason === 'refusal' ? 'refused' : 'error'
      await update($, statsA, (s): Stats => ({ ...s, phase, turnDurationMs: e.durationMs }))
      scheduleRefresh($)
    }
    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await setContext($, e.context)
    return next(e)
  })

  // —— 侧栏 ——

  on('ui.scroll', { requestId: PANE }, async ($, e) => {
    if ((await read($, modeA)) === 'search') {
      const { hits } = await read($, searchA)
      await update($, hitScrollA, off => clamp(off + e.by, 0, Math.max(0, hits.length - hitLayout.rows)))
      return {}
    }
    const row = e.pointer?.row
    const isOverList = row !== undefined && row >= layout.listTop && row < layout.listTop + layout.listRows
    if (isOverList) {
      const max = Math.max(0, layout.listLen - layout.listRows)
      await update($, scrollA, s => ({ ...s, list: clamp(s.list + e.by, 0, max) }))
    } else {
      await scrollDiff($, e.by)
    }
    return {}
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const W = Math.max(24, e.props.bodyColumns)
    const R = Math.max(8, e.props.scroll.bodyRows)
    const snap = await read($, snapshotA)
    const selected = await read($, selectedA)
    const detail = await read($, detailA)
    const scroll = await read($, scrollA)

    const mode = await read($, modeA)
    const tabs = (
      <Box key="tabs" flexDirection="row" gap={1}>
        <Button key="tab-changes" plain hotkey="c" dimColor={mode !== 'changes'} variant={mode === 'changes' ? 'primary' : undefined} label="改动" onPress={() => setMode($, 'changes')} />
        <Button key="tab-search" plain hotkey="s" dimColor={mode !== 'search'} variant={mode === 'search' ? 'primary' : undefined} label="搜索" onPress={() => setMode($, 'search')} />
      </Box>
    )
    if (mode === 'search') {
      const search = await read($, searchA)
      const hitSel = await read($, hitSelA)
      const history = await read($, historyA)
      const hitOffsetRaw = await read($, hitScrollA)
      // 手机端没有输入框，只能用 /search 文字 搜。
      const table = $.ui.resolve(e)
      const Input = 'Input' in table ? table.Input : undefined
      const input = Input === undefined ? (
        <Text key="q-hint" dimColor>在输入框里运行 /search 文字</Text>
      ) : (
        <Input
          key="q"
          label="搜索 "
          placeholder="输入文字后回车，在仓库文件里查找"
          value={search.query}
          submitLabel="搜索"
          autoFocus
          onSubmit={(value: string) => runSearch($, value)}
        />
      )
      const searchBar = (
        <Box key="sbar" flexDirection="row" gap={1}>
          {tabs}
          <Text dimColor>│</Text>
          <Button key="hit-next" plain hotkey="j" label="下个" onPress={() => moveHit($, 1)} />
          <Button key="hit-prev" plain hotkey="k" label="上个" onPress={() => moveHit($, -1)} />
        </Box>
      )
      const rule = (key: string, text: string) => (
        <Text key={key} dimColor wrap="truncate-end">{clipW(text + '─'.repeat(Math.max(0, W - width(text))), W)}</Text>
      )

      // 结果列表
      const hitRows = Math.max(3, Math.floor((R - 4) * 0.5))
      const hitOffset = clamp(hitOffsetRaw, 0, Math.max(0, search.hits.length - hitRows))
      hitLayout.rows = hitRows
      const shownHits = search.hits.slice(hitOffset, hitOffset + hitRows)
      let resultEls: RenderElement[]
      if (search.status === 'idle') resultEls = [<Text key="s-idle" dimColor>按字面查找；查询全小写时忽略大小写。包含未跟踪文件，跳过二进制文件。</Text>]
      else if (search.status === 'running') resultEls = [<Text key="s-run" color="inactive">搜索中…</Text>]
      else if (search.status === 'error') resultEls = [<Text key="s-err" color="error" wrap="wrap">搜索失败：{search.reason}</Text>]
      else if (search.hits.length === 0) resultEls = [<Text key="s-none" color="warning">没有找到“{search.query}”。</Text>]
      else {
        // 变量不能叫 h：h 是 JSX 的工厂函数。
        resultEls = shownHits.map(hit => {
          const id = hitId(hit)
          const isSel = id === hitSel
          const where = `${hit.path}:${hit.line}`
          const whereText = fitPath(where, Math.max(8, Math.floor((W - 2) * 0.45)))
          const room = Math.max(0, W - 3 - width(whereText))
          return (
            <Box key={`hit:${id}`} flexDirection="row">
              <Text color={isSel ? 'claude' : undefined} bold>{isSel ? '› ' : '  '}</Text>
              <Button key={`hit:${id}`} plain label={whereText} hover={{ color: 'suggestion', underline: true }} onPress={() => selectHit($, hit)} />
              <Text dimColor wrap="truncate-end"> {clipW(cleanLine(hit.text.trim()), room)}</Text>
            </Box>
          )
        })
      }
      const count =
        search.status === 'done'
          ? `── 结果 ${search.hits.length}${search.isCut ? '+（只显示前 ' + MAX_HITS + ' 条）' : ''}` +
            (search.hits.length > hitRows ? ` · ${hitOffset + 1}-${hitOffset + shownHits.length}` : '') + ' '
          : '── 结果 '

      // 提交记录
      const sel = search.hits.find(hit => hitId(hit) === hitSel)
      const histRows = Math.max(2, R - 4 - Math.min(hitRows, Math.max(1, resultEls.length)))
      let historyEls: RenderElement[] = []
      if (!sel || history === null || history.id !== hitSel) historyEls = [<Text key="h-none" dimColor>选择一条结果，查看它的提交记录。</Text>]
      else if (history.kind === 'loading') historyEls = [<Text key="h-load" color="inactive">读取提交记录…</Text>]
      else if (history.kind === 'error') historyEls = [<Text key="h-err" color="error" wrap="wrap">读取提交记录失败：{history.reason}</Text>]
      else {
        if (history.note) historyEls.push(<Text key="h-note" color="warning">{history.note}</Text>)
        if (history.commits.length > 0) {
          const more = history.commits.length >= MAX_COMMITS ? `，只列最近 ${MAX_COMMITS} 次` : ''
          historyEls.push(<Text key="h-ft" dimColor>这一行被改过 {history.commits.length} 次（从新到旧{more}）：</Text>)
        }
        for (const c of history.commits.slice(0, Math.max(0, histRows - historyEls.length))) {
          historyEls.push(
            <Box key={`c:${c.hash}`} flexDirection="row">
              <Text color={c === history.commits[0] ? 'claude' : 'subtle'}>{c === history.commits[0] ? '● ' : '· '}</Text>
              <Text color="suggestion">{c.hash} </Text>
              <Text color="warning">{c.time} </Text>
              <Text color="claude">{padW(clipW(c.author, 10), 10)} </Text>
              <Text wrap="truncate-end">{clipW(c.subject, Math.max(0, W - c.hash.length - 32))}</Text>
            </Box>,
          )
        }
      }
      return (
        <Box flexDirection="column">
          {searchBar}
          {input}
          {rule('r-res', count)}
          {resultEls}
          {rule('r-hist', sel ? `── 提交记录 · ${sel.path}:${sel.line} ` : '── 提交记录 ')}
          {historyEls}
        </Box>
      )
    }

    const title =
      snap.kind === 'ok'
        ? `${snap.branch} · ${snap.files.length} 项未提交（含会话前已有的）`
        : TITLE
    const toolbar = (
      <Box flexDirection="row" gap={1}>
        {tabs}
        <Text dimColor>│</Text>
        <Button key="refresh" plain hotkey="r" label="刷新" onPress={() => refresh($)} />
        <Button key="next" plain hotkey="j" label="下个" onPress={() => move($, 1)} />
        <Button key="prev" plain hotkey="k" label="上个" onPress={() => move($, -1)} />
        <Button key="pgdn" plain hotkey="d" label="下翻" onPress={() => scrollDiff($, Math.max(1, layout.diffRows - 2))} />
        <Button key="pgup" plain hotkey="u" label="上翻" onPress={() => scrollDiff($, -Math.max(1, layout.diffRows - 2))} />
      </Box>
    )
    const head = [
      <Text key="title" bold wrap="truncate-end">{clipW(title, W)}</Text>,
      toolbar,
    ]

    const notice = (text: string, color?: string) => (
      <Box flexDirection="column">
        {head}
        <Text color={color} wrap="wrap">{text}</Text>
      </Box>
    )
    if (snap.kind === 'loading') return notice('正在读取 Git 状态…', 'inactive')
    if (snap.kind === 'not-git') return notice(`当前目录不是 Git 仓库，没有可显示的改动。\n${snap.reason}`, 'warning')
    if (snap.kind === 'error') return notice(`读取 Git 状态失败：${snap.reason}`, 'error')
    if (snap.files.length === 0) return notice('工作区干净：没有未提交的改动。', 'success')

    // 文件列表区
    const rows = listRowsOf(snap.files)
    const listRows = Math.min(rows.length, Math.max(3, Math.floor((R - 3) * 0.4)))
    const listOffset = clamp(scroll.list, 0, Math.max(0, rows.length - listRows))
    const shown = rows.slice(listOffset, listOffset + listRows)
    const files = shown.flatMap(r => (r.kind === 'file' ? [r.file] : []))
    const addW = Math.max(0, ...files.map(f => (f.isBinary ? 3 : f.added === null ? 0 : String(f.added).length + 1)))
    const delW = Math.max(0, ...files.map(f => (f.isBinary || f.deleted === null ? 0 : String(f.deleted).length + 1)))
    const listEls = shown.map(r => {
      if (r.kind === 'head') return <Text key={`h:${r.label}`} dimColor bold>{r.label}</Text>
      const f = r.file
      const isSel = f.id === selected
      const add = f.isBinary ? 'bin' : f.added === null ? '' : `+${f.added}`
      const del = f.isBinary || f.deleted === null ? '' : `-${f.deleted}`
      const label = f.origPath ? `${f.origPath} → ${f.path}` : f.path
      const room = W - 4 - addW - delW - 2
      return (
        <Box key={`row:${f.id}`} flexDirection="row">
          <Text color={isSel ? 'claude' : undefined} bold>{isSel ? '› ' : '  '}</Text>
          <Text color={codeColor(f.code)}>{f.code} </Text>
          <Text color="success">{padW(add, addW)} </Text>
          <Text color="error">{padW(del, delW)} </Text>
          <Button
            key={`file:${f.id}`}
            plain
            label={fitPath(label, Math.max(4, room))}
            hover={{ color: 'suggestion', underline: true }}
            onPress={() => select($, f.id)}
          />
        </Box>
      )
    })

    // 详情区
    const diffRows = Math.max(1, R - 3 - listRows)
    const entry = snap.files.find(f => f.id === selected)
    let bodyRows: DiffRow[] = []
    let message: { text: string; color?: string } | undefined
    if (entry === undefined || detail === null || detail.id !== entry.id) message = { text: '选择一个文件查看改动。', color: 'inactive' }
    else if (detail.kind === 'loading') message = { text: '读取中…', color: 'inactive' }
    else if (detail.kind === 'binary') message = { text: '二进制文件，不显示内容。', color: 'warning' }
    else if (detail.kind === 'empty') message = { text: '没有文本差异（可能只改了文件权限或类型）。', color: 'inactive' }
    else if (detail.kind === 'error') message = { text: `读取 Diff 失败：${detail.reason}`, color: 'error' }
    else {
      if (rowsCache?.source !== detail.source) rowsCache = { source: detail.source, rows: parseDiffRows(detail.source) }
      bodyRows = detail.isCut ? [...rowsCache.rows, { t: 'note', s: '… 内容过长，只显示前一部分' }] : rowsCache.rows
    }
    const diffOffset = clamp(scroll.id === selected ? scroll.diff : 0, 0, Math.max(0, bodyRows.length - diffRows))
    const visible = bodyRows.slice(diffOffset, diffOffset + diffRows)
    const range = bodyRows.length > 0 ? ` · ${diffOffset + 1}-${diffOffset + visible.length}/${bodyRows.length}` : ''
    const caption = entry ? `── ${entry.path}（${AREA_LABEL[entry.area]}）${range} ` : '── '
    const oW = Math.max(1, ...visible.map(r => String(r.o ?? '').length))
    const nW = Math.max(1, ...visible.map(r => String(r.n ?? '').length))
    const gutter = oW + nW + 2
    const diffEls = message
      ? [<Text key="msg" color={message.color} wrap="wrap">{message.text}</Text>]
      : visible.map((r, i) => {
          if (r.t === 'hunk' || r.t === 'note') {
            return <Text key={`d:${diffOffset + i}`} color="subtle" wrap="truncate-end">{clipW(cleanLine(r.s), W)}</Text>
          }
          const mark = r.t === 'add' ? '+' : r.t === 'del' ? '-' : ' '
          const text = padW(clipW(mark + cleanLine(r.s), W - gutter), W - gutter)
          const bg = r.t === 'add' ? 'diffAdded' : r.t === 'del' ? 'diffRemoved' : undefined
          return (
            <Box key={`d:${diffOffset + i}`} flexDirection="row">
              <Text dimColor>{`${String(r.o ?? '').padStart(oW)} ${String(r.n ?? '').padStart(nW)} `}</Text>
              <Text backgroundColor={bg} wrap="truncate-end">{text}</Text>
            </Box>
          )
        })

    Object.assign(layout, {
      listTop: 2,
      listRows,
      listLen: rows.length,
      diffRows,
      diffLen: bodyRows.length,
      detailId: entry?.id ?? null,
    })

    return (
      <Box flexDirection="column">
        {head}
        {listEls}
        <Text dimColor wrap="truncate-end">{clipW(caption + '─'.repeat(Math.max(0, W - width(caption))), W)}</Text>
        {diffEls}
      </Box>
    )
  })

  // —— 请求状态栏 ——

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const s = await read($, statsA)
    const isCompact = await read($, compactA)
    const isRunningTurn = s.turnStartedAt !== null && (s.phase === 'requesting' || s.phase === 'tool')
    const now = isRunningTurn ? await read($, nowA) : 0
    const elapsed = isRunningTurn ? Math.max(0, now - (s.turnStartedAt ?? now)) : s.turnDurationMs
    const W = Math.max(20, e.props.bodyColumns)
    const toggle = (
      <Button
        key="info"
        plain
        hotkey="i"
        dimColor
        label={isCompact ? '展开' : '收起'}
        onPress={() => update($, compactA, v => !v)}
      />
    )
    // 打开/关闭侧栏：鼠标点它；或绑定 app:toggleReplTab 的快捷键（见 README），在输入框里直接按。
    const paneButton = (
      <Button
        key="pane"
        plain
        hotkey="c"
        action="app:toggleReplTab"
        dimColor
        label="改动"
        onPress={() => togglePane($)}
      />
    )
    // 两个按钮占 12 列，其余留给文字。
    const draw = (key: string, segs: Seg[], room: number) => (
      <Box key={key} flexDirection="row">
        {clipSegs(segs, room).map((g, i) => (
          <Text key={`${key}:${i}`} color={g.color} dimColor={g.dim} bold={g.bold}>{g.text}</Text>
        ))}
      </Box>
    )
    const head: Seg[] = [
      { text: `● ${PHASE_LABEL[s.phase]}`, color: PHASE_COLOR[s.phase], bold: true },
      { text: '  ' },
      { text: s.model ?? '模型暂无', color: 'claude' },
      { text: '  上下文 ', dim: true },
      { text: contextText(s), color: contextColor(s.context.percent) },
    ]
    if (isCompact) {
      head.push(
        { text: '  本轮 ', dim: true },
        { text: fmtMs(elapsed), color: 'claude' },
        { text: ' · 请求 ', dim: true },
        { text: String(s.turnRequests) },
        { text: ' · 工具 ', dim: true },
        { text: String(s.turnTools) },
      )
    }
    return (
      <Box flexDirection="column">
        <Box flexDirection="row">
          {draw('head', head, W - 12)}
          <Text> </Text>
          {paneButton}
          <Text> </Text>
          {toggle}
        </Box>
        {!isCompact && scopeRows(s, elapsed).map(r => draw(`scope:${r.key}`, r.segs, W))}
      </Box>
    )
  })
}

/** 一段带颜色的文字。 */
type Seg = { text: string; color?: string; dim?: boolean; bold?: boolean }

/** 按显示宽度从左往右截，超出的段丢掉，最后一段截半。 */
function clipSegs(segs: readonly Seg[], room: number): Seg[] {
  const out: Seg[] = []
  let left = room
  for (const g of segs) {
    if (left <= 0) break
    const text = clipW(g.text, left)
    if (text === '') break
    out.push({ ...g, text })
    left -= width(text)
  }
  return out
}

/** 每个指标一种颜色，三行同一列颜色一致；“暂无”统一变暗。 */
const METRIC_COLOR = {
  input: 'text',
  output: 'success',
  cacheRead: 'suggestion',
  cacheWrite: 'warning',
  time: 'claude',
  count: 'text',
} as const

const SCOPES = [
  { key: 'last', label: '最近一次', color: 'suggestion' },
  { key: 'turn', label: '本轮', color: 'claude' },
  { key: 'session', label: '会话', color: 'merged' },
] as const

/** 三种口径各一行，列对齐。 */
function scopeRows(s: Stats, turnMs: number | null): { key: string; segs: Seg[] }[] {
  const values: Record<(typeof SCOPES)[number]['key'], { u: Usage4 | null; ms: string; req: string; tools: string }> = {
    last: {
      u: s.last?.usage ?? null,
      ms: fmtMs(s.last?.durationMs),
      req: s.last ? '1' : '暂无',
      tools: s.last ? String(s.last.tools) : '暂无',
    },
    turn: { u: s.turnUsage, ms: fmtMs(turnMs), req: String(s.turnRequests), tools: String(s.turnTools) },
    session: { u: s.session.usage, ms: '—', req: String(s.session.requests), tools: String(s.session.tools) },
  }
  const cell = (name: string, value: string, color: string, w: number): Seg[] => [
    { text: `${name} `, dim: true },
    { text: padW(value, w), color: value === '暂无' || value === '—' ? undefined : color, dim: value === '暂无' || value === '—' },
  ]
  return SCOPES.map(scope => {
    const v = values[scope.key]
    return {
      key: scope.key,
      segs: [
        { text: padW(scope.label, 9), color: scope.color, bold: true },
        ...cell('入', fmtTokens(v.u?.input), METRIC_COLOR.input, 7),
        ...cell('出', fmtTokens(v.u?.output), METRIC_COLOR.output, 7),
        ...cell('缓存读', fmtTokens(v.u?.cacheRead), METRIC_COLOR.cacheRead, 7),
        ...cell('缓存写', fmtTokens(v.u?.cacheWrite), METRIC_COLOR.cacheWrite, 7),
        ...cell('耗时', v.ms, METRIC_COLOR.time, 7),
        ...cell('请求', v.req, METRIC_COLOR.count, 5),
        ...cell('工具', v.tools, METRIC_COLOR.count, 4),
      ],
    }
  })
}

function contextColor(percent: number | null): string | undefined {
  if (percent === null) return undefined
  return percent >= 85 ? 'error' : percent >= 60 ? 'warning' : 'success'
}

function contextText(s: Stats): string {
  const { tokens, window, percent } = s.context
  if (tokens === null) return '暂无'
  return `${fmtTokens(tokens)}/${fmtTokens(window)}${percent === null ? '' : ` ${percent}%`}`
}

/** 请求详情表：最近一次请求、本轮、整个会话三列，拿不到的写“暂无”。 */
export function infoLines(s: Stats, now: number): string[] {
  const cols = ['最近一次', '本轮', '会话']
  const pick = (u: Usage4 | null | undefined, k: keyof Usage4) => fmtTokens(u ? u[k] : null)
  const isRunningTurn = s.turnStartedAt !== null && (s.phase === 'requesting' || s.phase === 'tool')
  const turnMs = isRunningTurn ? Math.max(0, now - (s.turnStartedAt ?? now)) : s.turnDurationMs
  const table: [string, string, string, string][] = [
    ['输入', pick(s.last?.usage, 'input'), pick(s.turnUsage, 'input'), pick(s.session.usage, 'input')],
    ['输出', pick(s.last?.usage, 'output'), pick(s.turnUsage, 'output'), pick(s.session.usage, 'output')],
    ['缓存读取', pick(s.last?.usage, 'cacheRead'), pick(s.turnUsage, 'cacheRead'), pick(s.session.usage, 'cacheRead')],
    ['缓存写入', pick(s.last?.usage, 'cacheWrite'), pick(s.turnUsage, 'cacheWrite'), pick(s.session.usage, 'cacheWrite')],
    ['耗时', fmtMs(s.last?.durationMs), fmtMs(turnMs), '—'],
    ['请求次数', s.last ? '1' : '暂无', String(s.turnRequests), String(s.session.requests)],
    ['工具调用', s.last ? String(s.last.tools) : '暂无', String(s.turnTools), String(s.session.tools)],
  ]
  const w = [10, 10, 10, 10]
  const row = (cells: string[]) => cells.map((c, i) => padW(c, w[i] ?? 10)).join('')
  return [
    row(['口径', ...cols]),
    ...table.map(row),
    `模型 ${s.last?.model ?? s.model ?? '暂无'} · 上下文 ${contextText(s)}` +
      (s.context.window === null ? '' : `（窗口 ${fmtTokens(s.context.window)}）`),
    '最近一次=主对话最近一次模型请求，耗时为本地计时；最近一次的工具调用=该响应要求的工具数。',
    '本轮=当前或上一次提问；会话=本插件加载以来，/clear 清零；子代理不计入。token 均为 API 报告值。',
  ]
}

