// 纯函数：解析 git 输出、拆 Diff 行、格式化数字。不碰 $，测试直接调用。
import type { Blame, Commit, FileArea, FileEntry, GrepHit, Usage4 } from '../types'

/** 单个 Diff 在状态里最多保留的字符数，超过就在行边界截断并提示。 */
export const DIFF_CHAR_LIMIT = 1_000_000

const UNMERGED = new Set(['DD', 'AU', 'UD', 'UA', 'DU', 'AA', 'UU'])

export type StatusItem = { xy: string; path: string; origPath?: string }

/** 解析 `git status --porcelain=v1 -z`。重命名和复制后面多跟一个原路径字段。 */
export function parseStatus(out: string): StatusItem[] {
  const parts = out.split('\0')
  const items: StatusItem[] = []
  for (let i = 0; i < parts.length; i++) {
    const field = parts[i] ?? ''
    if (field.length < 4) continue
    const xy = field.slice(0, 2)
    const item: StatusItem = { xy, path: field.slice(3) }
    if (/[RC]/.test(xy)) item.origPath = parts[++i]
    items.push(item)
  }
  return items
}

export type NumStat = { added: number | null; deleted: number | null; isBinary: boolean }

function toNumStat(a: string, d: string): NumStat {
  const isBinary = a === '-'
  return { added: isBinary ? null : Number(a), deleted: isBinary ? null : Number(d), isBinary }
}

/** 解析 `git diff --numstat -z`。重命名时路径字段为空，后面依次是原路径和新路径。 */
export function parseNumstat(out: string): Map<string, NumStat> {
  const parts = out.split('\0')
  const map = new Map<string, NumStat>()
  for (let i = 0; i < parts.length; i++) {
    const m = /^(-|\d+)\t(-|\d+)\t([\s\S]*)$/.exec(parts[i] ?? '')
    if (!m) continue
    let path = m[3] ?? ''
    if (path === '') {
      i++ // 原路径
      path = parts[++i] ?? ''
    }
    map.set(path, toNumStat(m[1] ?? '-', m[2] ?? '-'))
  }
  return map
}

/** 解析 `git diff --no-index --numstat -- /dev/null <file>` 的一行（未跟踪文件用）。 */
export function parseNoIndexNumstat(out: string): NumStat | undefined {
  const m = /^(-|\d+)\t(-|\d+)\t/.exec(out)
  return m ? toNumStat(m[1] ?? '-', m[2] ?? '-') : undefined
}

/** 把 status 和 numstat 合成侧栏的行。同一文件可以同时出现在已暂存和未暂存里。 */
export function buildEntries(
  status: StatusItem[],
  cached: Map<string, NumStat>,
  worktree: Map<string, NumStat>,
  untracked: Map<string, NumStat>,
): FileEntry[] {
  const out: FileEntry[] = []
  const push = (area: FileArea, code: string, item: StatusItem, stat: NumStat | undefined) => {
    out.push({
      id: `${area}:${item.path}`,
      area,
      path: item.path,
      ...(area === 'staged' && item.origPath !== undefined ? { origPath: item.origPath } : {}),
      code,
      added: stat?.added ?? null,
      deleted: stat?.deleted ?? null,
      isBinary: stat?.isBinary ?? false,
    })
  }
  for (const item of status) {
    const x = item.xy[0] ?? ' '
    const y = item.xy[1] ?? ' '
    if (item.xy === '??') push('untracked', '?', item, untracked.get(item.path))
    else if (item.xy === '!!') continue
    else if (UNMERGED.has(item.xy)) push('unstaged', 'U', item, worktree.get(item.path))
    else {
      if (x !== ' ') push('staged', x, item, cached.get(item.path))
      if (y !== ' ') push('unstaged', y, item, worktree.get(item.path))
    }
  }
  const order: Record<FileArea, number> = { staged: 0, unstaged: 1, untracked: 2 }
  return out.sort((a, b) => order[a.area] - order[b.area] || (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))
}

/** 查看某一行 Diff 的 git 参数。未跟踪文件和 /dev/null 比，所以整份内容都显示成新增。 */
export function diffArgv(entry: FileEntry): string[] {
  const base = ['diff', '--no-color', '--no-ext-diff']
  if (entry.area === 'untracked') return [...base, '--no-index', '--', '/dev/null', entry.path]
  if (entry.area === 'staged') {
    return [...base, '--cached', '-M', '--', ...(entry.origPath ? [entry.origPath] : []), entry.path]
  }
  return [...base, '--', entry.path]
}

export type DiffBody =
  | { kind: 'diff'; source: string; isCut: boolean }
  | { kind: 'binary' }
  | { kind: 'empty' }

/** 去掉第一个 `@@` 之前的文件头；没有 hunk 时判断是二进制还是只有模式变化。 */
export function toDiffBody(raw: string, isTruncated = false, limit = DIFF_CHAR_LIMIT): DiffBody {
  const start = raw.startsWith('@@') ? 0 : raw.indexOf('\n@@') + 1
  if (start === 0 && !raw.startsWith('@@')) {
    return /^(Binary files |GIT binary patch)/m.test(raw) ? { kind: 'binary' } : { kind: 'empty' }
  }
  let source = raw.slice(start).replace(/\n$/, '')
  let isCut = isTruncated
  if (source.length > limit) {
    source = source.slice(0, source.lastIndexOf('\n', limit))
    isCut = true
  }
  return { kind: 'diff', source, isCut }
}

export type DiffRow = { t: 'hunk' | 'ctx' | 'add' | 'del' | 'note'; o?: number; n?: number; s: string }

/** 把 hunk 文本拆成带新旧行号的行。行号从 hunk 头 `@@ -a,b +c,d @@` 起算。 */
export function parseDiffRows(source: string): DiffRow[] {
  const rows: DiffRow[] = []
  let o = 0
  let n = 0
  for (const line of source.split('\n')) {
    const head = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(line)
    if (head) {
      o = Number(head[1])
      n = Number(head[2])
      rows.push({ t: 'hunk', s: line })
    } else if (line[0] === '+') rows.push({ t: 'add', n: n++, s: line.slice(1) })
    else if (line[0] === '-') rows.push({ t: 'del', o: o++, s: line.slice(1) })
    else if (line[0] === '\\') rows.push({ t: 'note', s: line })
    else rows.push({ t: 'ctx', o: o++, n: n++, s: line.slice(1) })
  }
  return rows
}

/** 下一个或上一个文件的 id；列表为空时为 null，没有选中时取第一个。 */
export function step(files: readonly FileEntry[], current: string | null, by: 1 | -1): string | null {
  const at = files.findIndex(f => f.id === current)
  if (at < 0) return files[0]?.id ?? null
  return files[Math.min(files.length - 1, Math.max(0, at + by))]?.id ?? null
}

/** 刷新后保留选择：原 id 还在就留着；同一路径换了区域就跟过去；都没有就取第一个。 */
export function keepSelection(files: readonly FileEntry[], current: string | null): string | null {
  if (current !== null) {
    if (files.some(f => f.id === current)) return current
    const path = current.slice(current.indexOf(':') + 1)
    const moved = files.find(f => f.path === path)
    if (moved) return moved.id
  }
  return files[0]?.id ?? null
}

export function addUsage(a: Usage4 | null, b: Usage4): Usage4 {
  if (a === null) return { ...b }
  return {
    input: a.input + b.input,
    output: a.output + b.output,
    cacheRead: a.cacheRead + b.cacheRead,
    cacheWrite: a.cacheWrite + b.cacheWrite,
  }
}

export function fmtTokens(n: number | null | undefined): string {
  if (n === null || n === undefined) return '暂无'
  if (n < 1000) return String(n)
  if (n < 1_000_000) return `${(n / 1000).toFixed(n < 10_000 ? 1 : 0)}k`
  return `${(n / 1_000_000).toFixed(n < 10_000_000 ? 2 : 1)}M`
}

export function fmtMs(ms: number | null | undefined): string {
  if (ms === null || ms === undefined) return '暂无'
  if (ms < 1000) return `${Math.round(ms)}ms`
  const s = ms / 1000
  if (s < 60) return `${s.toFixed(1)}s`
  return `${Math.floor(s / 60)}m${Math.round(s % 60)}s`
}

/** 终端显示宽度：CJK 和全角字符按 2 列算。ponytail: 粗略区间判断，够用于对齐和截断。 */
export function width(s: string): number {
  let w = 0
  for (const ch of s) {
    const c = ch.codePointAt(0) ?? 0
    w += c >= 0x1100 && (c <= 0x115f || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
      (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) ||
      (c >= 0xffe0 && c <= 0xffe6) || (c >= 0x1f300 && c <= 0x1faff) || (c >= 0x20000 && c <= 0x3fffd)) ? 2 : 1
  }
  return w
}

export function padW(s: string, w: number): string {
  return s + ' '.repeat(Math.max(0, w - width(s)))
}

/** 按显示宽度截到 room 列以内。 */
export function clipW(s: string, room: number): string {
  if (width(s) <= room) return s
  let out = ''
  let w = 0
  for (const ch of s) {
    const cw = width(ch)
    if (w + cw > room) break
    out += ch
    w += cw
  }
  return out
}

/** 制表符展开成空格，其他控制字符换成替换符，保证一行只占一行。 */
export function cleanLine(s: string): string {
  return s.replace(/\t/g, '    ').replace(/[\u0000-\u001f\u007f]/g, '�')
}

/** 路径太宽时保留结尾，前面用省略号。 */
export function fitPath(path: string, room: number): string {
  if (width(path) <= room) return path
  const chars = [...path]
  let out = ''
  for (let i = chars.length - 1; i >= 0 && width(out) + width(chars[i] ?? '') <= room - 1; i--) out = chars[i] + out
  return `…${out}`
}

// —— 搜索与提交记录 ——

/** 解析 `git grep -n -z`：每行是 `路径\0行号\0内容`。超过 limit 条只留前面的。 */
export function parseGrep(out: string, limit: number): { hits: GrepHit[]; isCut: boolean } {
  const hits: GrepHit[] = []
  let isCut = false
  for (const line of out.split('\n')) {
    if (line === '') continue
    const a = line.indexOf('\0')
    const b = line.indexOf('\0', a + 1)
    if (a < 0 || b < 0) continue
    if (hits.length >= limit) {
      isCut = true
      break
    }
    hits.push({ path: line.slice(0, a), line: Number(line.slice(a + 1, b)), text: line.slice(b + 1) })
  }
  return { hits, isCut }
}

/** 搜索参数：按字面匹配；查询里没有大写字母时忽略大小写。未跟踪文件也搜，二进制文件跳过。 */
export function grepArgv(query: string): string[] {
  return ['grep', '-n', '-I', '-z', '--no-color', '--untracked', ...(/[A-Z]/.test(query) ? [] : ['-i']), '-F', '-e', query, '--']
}

/** 把 git 的秒级时间和时区（如 `+0800`）格式化成作者当地的 `YYYY-MM-DD HH:MM`。 */
export function fmtGitTime(seconds: number, tz: string): string {
  const m = /^([+-])(\d\d)(\d\d)$/.exec(tz)
  const offset = m ? (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3])) : 0
  const d = new Date((seconds + offset * 60) * 1000)
  const p = (n: number) => String(n).padStart(2, '0')
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`
}

/** 解析 `git blame --porcelain -L n,n` 的一行结果。 */
export function parseBlame(out: string): Blame | undefined {
  const lines = out.split('\n')
  const head = /^([0-9a-f]{40}) (\d+) /.exec(lines[0] ?? '')
  const hash = head?.[1]
  if (!hash) return undefined
  const field = (name: string) => lines.find(l => l.startsWith(`${name} `))?.slice(name.length + 1) ?? ''
  const isUncommitted = /^0+$/.test(hash)
  return {
    hash: hash.slice(0, 8),
    author: field('author'),
    time: fmtGitTime(Number(field('author-time')), field('author-tz')),
    summary: field('summary'),
    isUncommitted,
    origLine: Number(head?.[2]),
    origPath: field('filename'),
  }
}

/** `git log` 用的格式：字段用 0x1f 分隔，避免和提交说明里的字符冲突。 */
export const LOG_FORMAT = '--format=%h%x1f%an%x1f%ad%x1f%s'
export const LOG_DATE = '--date=format:%Y-%m-%d %H:%M'

export function parseLog(out: string): Commit[] {
  return out.split('\n').flatMap(line => {
    const [hash, author, time, subject] = line.split('\x1f')
    return hash && author !== undefined && time !== undefined ? [{ hash, author, time, subject: subject ?? '' }] : []
  })
}

