// changes-dashboard 的 $.state 契约。

/** 改动所在区域：已暂存、未暂存、未跟踪。 */
export type FileArea = 'staged' | 'unstaged' | 'untracked'

/** 侧栏里的一行。同一个文件既有暂存又有未暂存改动时，会出现两行。 */
export type FileEntry = {
  /** `${area}:${path}`，选择和按钮都靠它定位。 */
  id: string
  area: FileArea
  /** 相对仓库根目录。 */
  path: string
  /** 重命名或复制前的路径，只在已暂存行上有。 */
  origPath?: string
  /** git status 的单字母状态：M A D R C T U ?。 */
  code: string
  /** 新增、删除行数；二进制文件或 git 没给出时为 null。 */
  added: number | null
  deleted: number | null
  isBinary: boolean
}

export type Snapshot =
  | { kind: 'loading' }
  | { kind: 'not-git'; reason: string }
  | { kind: 'error'; reason: string }
  | { kind: 'ok'; root: string; branch: string; files: FileEntry[] }

export type Detail =
  | { id: string; kind: 'loading' }
  | { id: string; kind: 'diff'; source: string; isCut: boolean }
  | { id: string; kind: 'binary' }
  | { id: string; kind: 'empty' }
  | { id: string; kind: 'error'; reason: string }

/** API 报告的四个 token 数。 */
export type Usage4 = { input: number; output: number; cacheRead: number; cacheWrite: number }

export type Phase = 'idle' | 'requesting' | 'tool' | 'done' | 'aborted' | 'refused' | 'error'

/** 只统计主对话；子代理的请求和工具调用不计入。会话累计从本 mod 加载时开始。 */
export type Stats = {
  /** 最近一次主对话请求用的模型；还没有请求时是 /model 的值。 */
  model: string | null
  phase: Phase
  turnStartedAt: number | null
  /** 本轮结束后才有，取引擎报告的 durationMs。 */
  turnDurationMs: number | null
  turnRequests: number
  turnTools: number
  /** 本轮内 API 报告过的用量之和；一次都没报告时为 null。 */
  turnUsage: Usage4 | null
  last: {
    model: string | null
    usage: Usage4 | null
    durationMs: number
    stopReason: string | null
    /** 这次响应要求执行的工具数。 */
    tools: number
  } | null
  session: { requests: number; tools: number; usage: Usage4 | null }
  /** 上下文占用，取自引擎的 session.usage / session.measure。 */
  context: { tokens: number | null; window: number | null; percent: number | null }
}

/** 一处搜索结果；路径相对仓库根目录。 */
export type GrepHit = { path: string; line: number; text: string }

export type Search = {
  query: string
  status: 'idle' | 'running' | 'done' | 'error'
  hits: GrepHit[]
  /** 结果超过上限，只保留了前面的。 */
  isCut: boolean
  reason: string | null
}

/** 某一行最后一次被谁改：取自 git blame。 */
export type Blame = {
  hash: string
  author: string
  time: string
  summary: string
  isUncommitted: boolean
  /** 这一行在那次提交里的行号和路径；工作区有未提交改动时，和搜索到的行号可能不同。 */
  origLine: number
  origPath: string
}

export type Commit = { hash: string; author: string; time: string; subject: string }

/** 选中的搜索结果那一行的提交记录，从新到旧。 */
export type History =
  | { id: string; kind: 'loading' }
  | { id: string; kind: 'ok'; blame: Blame | null; note: string | null; commits: Commit[] }
  | { id: string; kind: 'error'; reason: string }

declare module 'claude-code' {
  interface PluginState {
    'changes-dashboard': {
      snapshot: Snapshot
      selected: string | null
      detail: Detail | null
      /** 侧栏滚动位置：Diff 的首行（属于哪个文件）和文件列表的首行。 */
      scroll: { id: string | null; diff: number; list: number }
      stats: Stats
      /** 请求进行中每秒更新一次。只有状态栏读它，侧栏不跟着重画。 */
      now: number
      /** 侧栏显示改动还是搜索。 */
      mode: 'changes' | 'search'
      search: Search
      /** 选中的搜索结果，`${path}:${line}`。 */
      hitSel: string | null
      /** 搜索结果列表的首行。 */
      hitScroll: number
      history: History | null
      /** 状态栏是否收成一行。默认展开，三种口径各一行。 */
      compact: boolean
    }
  }
}
